// Proprietà dell'insegna: testo, stile, carattere, forma, riempimento, contorni, ombra e neon, a gruppi.
function pgSignProps(it){const pt=ptName(),opts=a=>a,sel=(id,l,v,o)=>ppS(id,l,v,o);return `<h3>Scritta</h3>`+ppT('text','Testo dell’insegna',it.text,'Puoi andare a capo per più righe (la scritta curva usa una riga sola) e usare i campi, per esempio «Nome».',2)+
 sel('style','Stile',it.style&&PG_SIGN_STYLES[it.style]?it.style:'',[['','Personalizzato'],...Object.entries(PG_SIGN_STYLES).map(([k,x])=>[k,x[0]])])+sel('font','Carattere',it.font,FONTS.map(f=>[f,f]))+
 ppK('bold','Grassetto',it.bold)+' '+ppK('italic','Corsivo',it.italic)+' '+ppK('caps','Tutto maiuscolo',it.caps)+ppK('fitSign','Adatta la scritta alla cornice',it.fit!==false)+(it.fit===false?ppF('size',`Dimensione (${pt})`,pgFmt(pgToPt(it.size))):'')+
 ppR('ls','Spaziatura tra le lettere',-5,40,it.ls||0,v=>v+'%')+(it.shape==='flat'||!it.shape?sel('align','Allineamento',it.align,[['left','A sinistra'],['center','Al centro'],['right','A destra']]):'')+
 `<h3>Forma</h3>`+sel('shape','Forma della scritta',it.shape||'flat',PG_SIGN_SHAPES)+(it.shape&&it.shape!=='flat'&&it.shape!=='circle'?ppR('curve','Curvatura',0,100,it.curve??50,v=>v+'%'):'')+
 `<h3>Riempimento e contorno</h3>`+sel('fillType','Riempimento',it.fillType,PG_SIGN_FILLS)+(it.fillType==='solid'||it.fillType==='grad'?ppC('c1',it.fillType==='grad'?'Primo colore':'Colore',it.c1):'')+(it.fillType==='grad'?ppC('c2','Secondo colore',it.c2)+ppR('angle','Direzione della sfumatura',0,360,it.angle||0,v=>v+'°','°',15):'')+
 (it.fillType==='image'?`<div class="pg-btns">${ppBtn('pgChooseImage',it.img?'Cambia immagine…':'Scegli immagine…')}</div>`:'')+ppR('ow','Contorno',0,15,it.ow||0,v=>v+'%','%',.5)+(it.ow>0?ppC('oc','Colore del contorno',it.oc)+ppS('dash','Tratto del contorno',it.dash||'',PG_DASHES):'')+ppR('ow2','Secondo contorno, all’esterno',0,15,it.ow2||0,v=>v+'%','%',.5)+(it.ow2>0?ppC('oc2','Colore del secondo contorno',it.oc2):'')+
 `<h3>Effetti</h3>`+sel('shadow','Ombra',it.shadow||'none',PG_SIGN_SHADOWS)+(it.shadow&&it.shadow!=='none'?ppC('shc','Colore dell’ombra',it.shc):'')+ppR('glow','Neon',0,100,it.glow||0,v=>v+'%')+(it.glow>0?ppC('gc','Colore del neon',it.gc):'')}
// Proprietà della stampa a tessere, nella parte del documento.
function pgTileProps(p){const t=p.tiles,g=pgTileGrid(p);return `<h3>Stampa a tessere</h3>`+ppK('ton','Stampa su più fogli da incollare',t.on,t.on?'':'Per poster e striscioni più grandi del foglio della stampante.')+
 (t.on?ppS('tsheet','Foglio',t.sheet,Object.entries(PG_SHEETS).map(([k,x])=>[k,x[0]]))+ppS('torient','Orientamento dei fogli',t.orient,[['auto','Quello che usa meno fogli'],['port','Verticale'],['land','Orizzontale']])+row2(ppF('tsafe','Margine dei fogli (mm)',pgFmt(t.safe/MM)),ppF('tover','Sovrapposizione (mm)',pgFmt(t.over/MM)))+
  ppK('tmarks','Segni di taglio e di sovrapposizione',t.marks)+ppK('tmap','Foglio di montaggio all’inizio',t.map)+`<p class="hint">Si stampa su ${pgTileSay(g)}. Con le guide attive vedi le tessere sulla pagina.</p>`:'')}
// Proprietà di più cornici scelte: allineamento tra loro, distribuzione, gruppo e blocco.
function pgMultiProps(items){const g=items.some(x=>x.g),lock=items.every(x=>x.lock);return `<div id="pp-multi"><p>${esc(items.map(x=>x.name).join(', '))}</p><h3>Allinea tra loro</h3><div class="pg-btns">${ppBtn('pgAlignL','A sinistra')}${ppBtn('pgAlignC','Al centro')}${ppBtn('pgAlignR','A destra')}${ppBtn('pgAlignT','In alto')}${ppBtn('pgAlignM','In mezzo')}${ppBtn('pgAlignB','In basso')}</div>
 <h3>Distribuisci a spazi uguali</h3><div class="pg-btns">${ppBtn('pgDistH','In orizzontale')}${ppBtn('pgDistV','In verticale')}</div>${items.length<3?'<p class="hint">Per distribuire servono almeno tre cornici.</p>':''}
 <h3>Insieme</h3><div class="pg-btns">${ppBtn('pgGroup','Raggruppa')}${g?ppBtn('pgUngroup','Separa il gruppo'):''}${ppBtn('pgLock',lock?'Sblocca':'Blocca')}${ppBtn('pgDelete','Elimina')}</div><p class="hint">Le frecce sulla pagina le spostano tutte; Alt+Maiusc+frecce le porta alla guida successiva. Esc toglie la scelta.</p></div>`}
